import { ref, watch, onScopeDispose, type Ref } from 'vue';

export function useOrders(customerId: Ref<string>) {
  // ref, not reactive: these get destructured by every caller, and a
  // destructured reactive object silently stops being reactive.
  const orders = ref<Order[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);

  let controller: AbortController | undefined;

  async function load(id: string) {
    controller?.abort(); // the previous request is now irrelevant
    controller = new AbortController();
    loading.value = true;
    error.value = null;

    try {
      const res = await fetch(`/api/customers/${id}/orders`, {
        signal: controller.signal,
      });
      if (!res.ok) throw new Error(`Failed: ${res.status}`);
      orders.value = await res.json();
    } catch (e) {
      if ((e as Error).name === 'AbortError') return; // expected, not a failure
      error.value = (e as Error).message;
    } finally {
      loading.value = false;
    }
  }

  watch(customerId, load, { immediate: true });

  // Without this, unmounting mid-request leaves the fetch running and the
  // handler writing into refs that no longer belong to a mounted component.
  onScopeDispose(() => controller?.abort());

  return { orders, loading, error, reload: () => load(customerId.value) };
}
